ResearchWorkbenchPage::~ResearchWorkbenchPage(){const bool visible=isVisible();invalidate();if(worker){worker->requestInterruption();worker->wait();}if(visible)try{persist(true);}catch(...) {}}
bool ResearchWorkbenchPage::foreground()const{return isVisible()&&window()->isVisible()&&!window()->isMinimized()&&window()->isActiveWindow()&&QGuiApplication::applicationState()==Qt::ApplicationActive;}
bool ResearchWorkbenchPage::currentOwner(QPointer<QWidget>owner,int epoch)const{return owner&&window()==owner&&generation==epoch&&isVisible()&&owner->isVisible()&&!owner->isMinimized()&&QGuiApplication::applicationState()==Qt::ApplicationActive;}
void ResearchWorkbenchPage::run(std::function<QJsonObject()>work,std::function<void(QJsonObject)>done){
 if(!foreground())return;
 if(running){status->setText("前一项正在收尾，请稍后重试。");return;}
 const int token=++generation;QPointer<QWidget>owner(window());running=true;ack->setChecked(false);confirm->setEnabled(false);status->setText("正在本机核对完整内容…");
 struct Result{QJsonObject value;QString error;};auto result=std::make_shared<Result>();
 auto*thread=QThread::create([result,work=std::move(work)]{try{result->value=work();}catch(const std::exception&e){result->error=QString::fromUtf8(e.what());}});worker=thread;
 connect(thread,&QThread::finished,this,[this,thread,token,owner,result,done=std::move(done)]{
  thread->wait();const bool finishedCurrent=worker==thread;if(finishedCurrent){worker=nullptr;running=false;}
  if(!currentOwner(owner,token)){
   // End this task's busy label without applying stale results or restoring confirmation.
   if(finishedCurrent&&status->text()==QStringLiteral("正在本机核对完整内容…"))status->setText("界面状态已变化，结果未显示；请重读历史或重新预览核对。");
   return;
  }
  if(!result->error.isEmpty()){status->setText(result->error);return;}done(result->value);
 });
 connect(thread,&QThread::finished,thread,&QObject::deleteLater);thread->start();
}
void ResearchWorkbenchPage::invalidate(){++generation;if(worker)worker->requestInterruption();pending={};pendingKind.clear();ack->setChecked(false);confirm->setEnabled(false);}
void ResearchWorkbenchPage::setReader(QString value,QString original){fullText=std::move(value);exportText=std::move(original);segment=0;renderReader();}
void ResearchWorkbenchPage::renderReader(){const int size=48000;int total=std::max(1,int((fullText.size()+size-1)/size));segment=std::max(0,std::min(segment,total-1));int a=segment*size,b=std::min(a+size,int(fullText.size()));if(a>0&&a<fullText.size()&&fullText[a].isLowSurrogate())--a;if(b>0&&b<fullText.size()&&fullText[b].isLowSurrogate())--b;reader->setPlainText(fullText.mid(a,b-a));position->setText(QString("第%1/%2段 · 完整%3字").arg(segment+1).arg(total).arg(fullText.size()));previous->setEnabled(segment>0);next->setEnabled(segment+1<total);}
QJsonArray ResearchWorkbenchPage::selected()const{QJsonArray out;for(int i=0;i<sources->count();++i){auto*item=sources->item(i);if(item->checkState()==Qt::Checked)out.append(item->data(Qt::UserRole).toString());}return out;}
QJsonObject ResearchWorkbenchPage::input()const{return {{"question",question->text()},{"riskProfile",risk->currentData().toString()},{"maxCandidates",maxCandidates->value()}};}
void ResearchWorkbenchPage::acceptBytes(QByteArray bytes){if(!foreground())return;applyBytes(std::move(bytes));}
void ResearchWorkbenchPage::applyBytes(QByteArray bytes,bool ownerApproved){try{need(bytes.size()<=8*1024*1024&&QString::fromUtf8(bytes).toUtf8()==bytes,"研究批次需完整有效UTF8且不超过8MiB");invalidate();raw->setPlainText(QString::fromUtf8(bytes));tabs->setCurrentIndex(0);persist(ownerApproved);}catch(const std::exception&e){status->setText(QString::fromUtf8(e.what()));}}
void ResearchWorkbenchPage::previewBatch(){
 if(!foreground()||!raw->isVisible()||running)return;invalidate();auto text=raw->toPlainText(),path=file,at=now();
 const bool legacy=QJsonDocument::fromJson(text.toUtf8()).object()["schema"]==externalResearchBatch::legacyBundleSchema;
 run([path,text,at,legacy]{externalResearchBatch::Store store(path);return legacy?store.previewLegacy(text,at):store.preview(text,at);},[this,legacy](QJsonObject p){
  if(legacy){setReader(externalResearchBatch::describeLegacyPreview(p),p["originalText"].toString());
   if(p["canConfirm"].toBool()){pending=p;pendingKind="legacy-batches";status->setText(QString("已完整预览%1份旧批次。勾选确认后只追加档案，关联已有运行；不重新投递。").arg(p["sourceRows"].toArray().size()));}
   else status->setText(p["conflicts"].toInt()?"旧批次与本机内容冲突；整批未覆盖。":"旧批次已有本机记录或迁移回执，未重复写入；删除项不会复活。");
  }else{auto v=p["displayBatch"].toObject();setReader((v.contains("legacySqlRow")?externalResearchBatch::describeLegacy(v):externalResearchBatch::describe(v))+"\n\n来源核对\n"+researchRuns::pretty(p["sourceChecks"])+"\n\n已有本机回执\n"+researchRuns::pretty(p["previousReceipt"]),v["originalText"].toString());
   if(p["replayed"].toBool())status->setText(p["savedRowsIntact"].toBool()&&p["receiptRowsMatch"].toBool()?"此批次已有本机回执，未重复写入或投递。":"此批次历史回执存在；当前原件/运行有删除或变化，未复活或覆盖。");
   else{pending=p;pendingKind="batch";status->setText("已完整预览。勾选确认后，批次与研究运行在同一事务保存。");}
  }try{persist();}catch(const std::exception&e){status->setText(QString::fromUtf8(e.what()));}
 });
}
void ResearchWorkbenchPage::refreshSources(){if(!foreground()||!sources->isVisible()||running)return;auto keep=selected();auto path=file;run([path]{return QJsonObject{{"materials",researchWorkbench::materials(businessRestore::Store(path).capture())}};},[this,keep](QJsonObject r){restoring=true;descriptors=r["materials"].toArray();sources->clear();for(auto v:descriptors){auto d=v.toObject();auto id=knowledgeAiHost::identity(d);auto*item=new QListWidgetItem(d["row"].toObject()["title"].toString()+" · "+id,sources);item->setData(Qt::UserRole,id);item->setFlags(item->flags()|Qt::ItemIsUserCheckable);item->setCheckState(keep.contains(id)?Qt::Checked:Qt::Unchecked);}restoring=false;status->setText("请明确勾选本次资料；不会把目录全部自动选入。");});}
void ResearchWorkbenchPage::previewPacket(){if(!foreground()||!question->isVisible()||running)return;try{invalidate();auto ctx=context?context():QJsonObject{};auto in=input();auto ids=selected();auto q=query->text(),path=file,at=now();run([path,in,ids,ctx,q,at]{return researchWorkbench::packetPreview(path,in,ids,ctx,q,at);},[this](QJsonObject p){pending=p;pendingKind="packet";setReader(researchWorkbench::packetReading(p),researchRuns::pretty(p["run"].toObject()["legacyOriginal"]));status->setText("已编排本机决策包，尚未调用AI。勾选后保存到原研究历史。");try{persist();}catch(const std::exception&e){status->setText(QString::fromUtf8(e.what()));}});}catch(const std::exception&e){status->setText(QString::fromUtf8(e.what()));}}
void ResearchWorkbenchPage::confirmSave(){
 if(running||pending.isEmpty()||!ack->isChecked()||!foreground()||!confirm->isVisible())return;
 try{auto held=pending;auto kind=pendingKind,path=file;auto ctx=kind=="packet"&&context?context():QJsonObject{};
  run([held,kind,path,ctx]{if(kind=="packet")return researchWorkbench::savePacket(path,held,true,ctx);externalResearchBatch::Store store(path);return kind=="legacy-batches"?store.commitLegacy(held,true):store.commit(held,true);},[this,held,kind](QJsonObject receipt){
   pending={};pendingKind.clear();setReader(fullText+"\n\n真实本机提交回执（不代表外部投递）\n"+researchRuns::pretty(receipt),exportText);
   status->setText(kind=="legacy-batches"?"旧批次档案已保存，原投递回执保留；本次没有投递或云同步核验。":"已保存并取得同库持久回执；可在保存历史及原研究历史回看。");try{persist();}catch(const std::exception&e){status->setText(QString::fromUtf8(e.what()));}
  });
 }catch(const std::exception&e){status->setText(QString::fromUtf8(e.what()));}
}
void ResearchWorkbenchPage::cancelPreview(){if(!foreground())return;invalidate();status->setText("预览已取消；尚未提交的内容没有写入。输入草稿保留。");try{persist();}catch(const std::exception&e){status->setText(QString::fromUtf8(e.what()));}}
void ResearchWorkbenchPage::reloadHistory(){if(!foreground()||!history->isVisible()||running)return;invalidate();auto path=file;run([path]{auto batches=externalResearchBatch::Store(path).history();auto s=businessRestore::Store(path).captureResearch();QJsonArray runs;for(auto w:s["payload"].toObject()["records"].toArray()){auto wrap=w.toObject();if(wrap["kind"]!="reports")continue;auto r=businessRestore::row(wrap);if(r["legacySource"]=="ai_research_runs"&&r["researchRun"].toObject()["runType"]=="decision-packet"&&r["researchRun"].toObject()["id"].toString().startsWith("f07-packet-"))runs.append(researchRuns::stored(r));}return QJsonObject{{"batches",batches},{"runs",runs}};},[this](QJsonObject result){history->clear();for(auto h:result["batches"].toArray()){auto o=h.toObject();auto*item=new QListWidgetItem(o["row"].toObject()["title"].toString()+(o["legacyMigration"].toBool()?" · 旧批次档案 / 原投递未复验":o["deliveryVerified"].toBool()?" · 本机回执已核":o["historicalDeliveryRecorded"].toBool()?" · 历史回执在，当前关联变化":" · 原回执缺失"),history);item->setData(Qt::UserRole,QJsonObject{{"kind","batch"},{"value",o}});}for(auto r:result["runs"].toArray()){auto*item=new QListWidgetItem(r.toObject()["title"].toString()+" · 本机决策包",history);item->setData(Qt::UserRole,QJsonObject{{"kind","packet"},{"value",r}});}status->setText("已重读本机历史；外部投递状态独立保留。");});}
QJsonObject ResearchWorkbenchPage::draftValue()const{return {{"schema","native-f07-draft/v1"},{"raw",raw->toPlainText()},{"question",question->text()},{"query",query->text()},{"risk",risk->currentData().toString()},{"maximum",maxCandidates->value()},{"sourceIds",selected()},{"tab",tabs->currentIndex()},{"segment",segment},{"fullText",fullText},{"exportText",exportText}};}
void ResearchWorkbenchPage::persist(bool ownerApproved){if(restoring||(!ownerApproved&&!foreground()))return;auto value=draftValue();if(value==property("f07CleanDraft").toJsonObject())return;marker=disk.save(value,marker);setProperty("f07CleanDraft",value);}
void ResearchWorkbenchPage::restoreDraft(){marker=disk.marker();if(marker.isEmpty())return;auto s=disk.read(marker);restoring=true;raw->setPlainText(s["raw"].toString());question->setText(s["question"].toString());query->setText(s["query"].toString());risk->setCurrentIndex(std::max(0,risk->findData(s["risk"].toString())));maxCandidates->setValue(s["maximum"].toInt(12));tabs->setCurrentIndex(std::clamp(s["tab"].toInt(),0,2));fullText=s["fullText"].toString();exportText=s["exportText"].toString();segment=s["segment"].toInt();sources->clear();for(auto id:s["sourceIds"].toArray()){auto*item=new QListWidgetItem(id.toString()+" · 待重读核对",sources);item->setData(Qt::UserRole,id.toString());item->setFlags(item->flags()|Qt::ItemIsUserCheckable);item->setCheckState(Qt::Checked);}restoring=false;invalidate();renderReader();status->setText("已恢复输入与完整阅读草稿；保存确认已清除，请重新预览核对当前来源。");setProperty("f07CleanDraft",draftValue());}
QJsonObject ResearchWorkbenchPage::saveState(){persist();return {{"schema","native-f07-marker/v1"},{"sha256",marker}};}
void ResearchWorkbenchPage::restoreState(QJsonObject s){try{need(s["schema"]=="native-f07-marker/v1"&&s["sha256"]==disk.marker(),"F07短状态与私有草稿不符");restoreDraft();}catch(const std::exception&e){status->setText(QString::fromUtf8(e.what()));}}
void ResearchWorkbenchPage::hideEvent(QHideEvent*e){invalidate();try{persist(true);}catch(const std::exception&error){status->setText(QString::fromUtf8(error.what()));}QWidget::hideEvent(e);}
